  `work_date` DATE NOT NULL,
  `check_in` DATETIME(3) NULL,
  `check_out` DATETIME(3) NULL,
  `status` ENUM('PRESENT','ABSENT','LATE','LEAVE','HALF_DAY') NOT NULL DEFAULT 'PRESENT',
  `overtime_minutes` INT NOT NULL DEFAULT 0,
  `notes` VARCHAR(255) NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted_at` DATETIME(3) NULL,
  `sync_version` INT UNSIGNED NOT NULL DEFAULT 1,
  `device_id` CHAR(36) NULL COMMENT 'uuid of the device that last wrote the row',
  `sync_status` ENUM('SYNCED','CONFLICT') NOT NULL DEFAULT 'SYNCED',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_attendance_uuid` (`uuid`),
  UNIQUE KEY `uq_attendance_employee_id_work_date` (`employee_id`,`work_date`),
  KEY `ix_attendance_work_date` (`work_date`),
  KEY `ix_attendance_updated_at` (`updated_at`),
  KEY `ix_attendance_sync` (`sync_status`,`device_id`),
  KEY `ix_attendance_branch_updated` (`branch_id`,`updated_at`),
  CONSTRAINT `fk_attendance_employee` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_attendance_branch` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `salaries` (
