  `base_amount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `overtime_amount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `bonus` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `deductions` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `advance_deduction` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `net_amount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `status` ENUM('DRAFT','APPROVED','PAID') NOT NULL DEFAULT 'DRAFT',
  `paid_at` DATETIME(3) NULL,
  `notes` VARCHAR(255) NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  `deleted_at` DATETIME(3) NULL,
  `sync_version` INT UNSIGNED NOT NULL DEFAULT 1,
  `device_id` CHAR(36) NULL COMMENT 'uuid of the device that last wrote the row',
  `sync_status` ENUM('SYNCED','CONFLICT') NOT NULL DEFAULT 'SYNCED',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_salaries_uuid` (`uuid`),
  KEY `ix_salaries_employee_id_period_month` (`employee_id`,`period_month`),
  KEY `ix_salaries_updated_at` (`updated_at`),
  KEY `ix_salaries_sync` (`sync_status`,`device_id`),
  KEY `ix_salaries_branch_updated` (`branch_id`,`updated_at`),
  CONSTRAINT `fk_salaries_employee` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_salaries_branch` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `expense_categories` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
