  KEY `ix_devices_updated_at` (`updated_at`),
  CONSTRAINT `fk_devices_branch` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Desktop installations. device_id in every syncable table = devices.uuid.';

CREATE TABLE `sync_batches` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `uuid` CHAR(36) NOT NULL,
  `device_id` BIGINT UNSIGNED NOT NULL,
  `batch_id` CHAR(36) NOT NULL,
  `status` ENUM('PROCESSING','COMPLETED','FAILED') NOT NULL DEFAULT 'PROCESSING',
  `change_count` INT NOT NULL DEFAULT 0,
  `success_count` INT NOT NULL DEFAULT 0,
  `conflict_count` INT NOT NULL DEFAULT 0,
  `failure_count` INT NOT NULL DEFAULT 0,
  `response_json` JSON NULL,
  `error_message` TEXT NULL,
  `received_at` DATETIME(3) NOT NULL,
  `processed_at` DATETIME(3) NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sync_batches_uuid` (`uuid`),
  UNIQUE KEY `uq_sync_batches_batch_id` (`batch_id`),
  KEY `ix_sync_batches_status` (`status`),
  KEY `ix_sync_batches_updated_at` (`updated_at`),
  CONSTRAINT `fk_sync_batches_device` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One row per client batch_id. Used for idempotency: a repeated batch returns response_json.';

CREATE TABLE `sync_records` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
