  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sync_records_uuid` (`uuid`),
  KEY `ix_sync_records_entity_entity_uuid` (`entity`,`entity_uuid`),
  KEY `ix_sync_records_status` (`status`),
  KEY `ix_sync_records_updated_at` (`updated_at`),
  CONSTRAINT `fk_sync_records_batch` FOREIGN KEY (`batch_id`) REFERENCES `sync_batches` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sync_conflicts` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
